entity.extra-code-model:

public void updateState(Enum state) {
    if (state==null) {
        throw new IllegalArgumentException("El state no puede ser nulo.");
    }
    String currentCodeState = this.getCodeState();

    StateEnum stateEnum = new StateEnum(state);
    if ((currentCodeState!=null) && (currentCodeState.equals(stateEnum.getCodeState()))) {
        return;
    }

    this.setCodeState(stateEnum.getCodeState());
    this.setNameState(com.educaflow.base.util.TextUtil.humanize(stateEnum.getCodeState()));
    this.setFechaUltimoEstado(java.time.LocalDateTime.now());
    this.setAbierto(!stateEnum.isClosed());
}


  public DocumentoPdf getDocumentoPdf(String documentoPdfFileName, Expediente expediente) {
      try {
          Class<?> callerClass = expediente.getClass();

          Path pathFileName= Path.of(documentoPdfFileName);

          try (InputStream in = callerClass.getResourceAsStream(documentoPdfFileName)) {
              if (in == null) {
                  throw new IOException("No se encontró el recurso: " + documentoPdfFileName);
              }
              DocumentoPdf documentoPdfVacio= DocumentoPdfFactory.getDocumentoPdf(in.readAllBytes(), pathFileName.getFileName().toString());

              Map<String, Object> contexto = Map.of("self", expediente,"now", java.time.LocalDateTime.now());

              DocumentoPdf documentoPdfRelleno = DocumentoPdfUtil.generate(documentoPdfVacio, contexto);

              return documentoPdfRelleno;

          }
      } catch (IOException e) {
          throw new RuntimeException("Error al cargar el documento PDF: " + documentoPdfFileName, e);
      }
  }

  public RegistroEntrada addRegistroEntrada(MetaFile documentoPdf,List<MetaFile> anexos) {
      DatosRegistroEntrada datosRegistroEntrada=new DatosRegistroEntrada(
          this.getCentro(),
          new PersonaRegistro(
              this.getPersonaSolicitante().getNombre()+ " "+this.getPersonaSolicitante().getApellidos(),
              this.getPersonaSolicitante().getDni()
          ),
          new PersonaRegistro(
               this.getPersonaInteresada().getNombre()+ " "+this.getPersonaInteresada().getApellidos(),
              this.getPersonaInteresada().getDni()
          ),
          this.getNumeroExpediente(),
          this.getName()
      );

      RegistroEntrada registroEntrada=Beans.get(RegistroEntradaService.class).createRegistroEntrada(datosRegistroEntrada,documentoPdf,anexos);

      this.setRegistroEntrada(registroEntrada);

      return registroEntrada;

  }


  public RegistroSalida addRegistroSalida(MetaFile documentoPdf,List<MetaFile> anexos) {
      DatosRegistroSalida datosRegistroSalida=new DatosRegistroSalida(
          this.getCentro()
      );

      RegistroSalida registroSalida=Beans.get(RegistroSalidaService.class).createRegistroSalida(datosRegistroSalida,documentoPdf,anexos);

      this.setRegistroSalida(registroSalida);

      return registroSalida;

  }
